sp_widget.client_script:
function($scope, $rootScope, $timeout) {
  var c = this;

  c.selectedYear = "";

  function atualizarIndicador() {
    c.server.get({ selectedYear: c.selectedYear }).then(function(response) {
      c.data = response.data;
      console.log("Indicador CAED atualizado:", c.selectedYear, c.data);
    });
  }

  $rootScope.$on('anoSelecionado', function(event, ano) {
    c.selectedYear = ano;
    atualizarIndicador();
  });

  atualizarIndicador();
}

sp_widget.css:
.financial-widget {
  border: 1px solid #ccc;
  border-radius: 4px;
  overflow: hidden;
  margin-top: 4rem;
}

.indicator-block {
  text-align: center;
  padding: 0;
}

.indicator-header {
  background-color: #EBEDF1;
  color: #021770;
  font-weight: 400;
  padding: 8px 10px;
  font-size: 14px;
  border-bottom: 1px solid #C7C7C7;
}

.indicator-value {
  color: #021770;
  font-size: 32px;
  font-weight: 400;
  padding: 10px 10px 15px;
}

sp_widget.script:
(function() {
  input = input || {};
  var table = 'x_sded9_portal_t_0_limite_de_endividamento';
  var selectedYear = input.selectedYear || "";

  // 1. Busca o ano mais recente DO INDICADOR CORRETO ('mga')
  if (!selectedYear) {
    var g = new GlideRecord(table);
    g.addQuery('indicador_de_endividamento_publico', 'caed'); // <--- ESSENCIAL
    g.orderByDesc('u_ano');
    g.setLimit(1);
    g.query();
    if (g.next())
      selectedYear = g.getValue('u_ano');
  }

  data.selectedYear = selectedYear;

  data.indicator = {
    value: '0%', 
    label: 'Realizado: ' + (selectedYear ? selectedYear : 'N/A')
  };

  // 2. Busca o dado (Realizado)
  var gr = new GlideRecord(table);
  gr.addQuery('indicador_de_endividamento_publico', 'caed'); // <--- ESSENCIAL PARA NÃO PEGAR DADO ERRADO

  if (selectedYear) {
    gr.addQuery('u_ano', selectedYear);
  }

  gr.orderByDesc('sys_created_on');
  gr.setLimit(1);
  gr.query();

  if (gr.next()) {
    var anoReal = gr.getValue('u_ano');
    // Busca o campo u_realizado pois é o "Valor Apurado"
    var valorApurado = gr.getValue('u_realizado') || '0'; 

    data.indicator.value = valorApurado + '%'; 
    data.indicator.label = 'Realizado ' + anoReal + ':';
    data.selectedYear = anoReal;
  }

})();
